      "anecdote": "李白（701-762），字太白，号青莲居士，祖籍陇西成纪，生于碎叶城（今吉尔吉斯斯坦托克马克），五岁随父迁居绵州昌隆（今四川江油）。少时博览经史，好剑术，喜任侠。二十五岁辞亲远游，遍历名山大川。天宝元年应诏入京，供奉翰林，贺知章读《蜀道难》惊呼其为“谪仙人”。因遭权贵谗毁，赐金放还。安史之乱中受邀入永王李璘幕府，永王兵败后牵连下狱，流放夜郎，途中遇赦东归。晚年漂泊当涂，投靠族叔李阳冰，762年病逝，相传因醉捞水中月而坠江卒。其诗豪放飘逸、想象奇绝，存世约千首，被誉为“诗仙”"
