      "anecdote": "李商隐（约813-约858），字义山，号玉溪生，怀州河内（今河南沁阳）人。早年丧父，家境孤寒，受知于令狐楚，得中进士。后娶泾原节度使王茂元之女，由此卷入牛李党争漩涡——令狐楚属牛党，王茂元属李党，被两党视为背恩负义之人，一生困顿不得志，仅任秘书省校书郎、弘农尉等微职。妻王氏早逝，留下深刻精神创伤。其诗深情绵邈、意境朦胧，擅长用典，开创无题诗传统，代表作《锦瑟》《无题》《夜雨寄北》等，被推为晚唐最杰出诗人。约858年病逝于郑州，享年约四十六岁"
