      "anecdote": "李清照（1084-约1155），号易安居士，齐州章丘（今山东章丘）人。出身书香门第，父李格非为苏门后四学士之一。自幼聪慧，少女时代便以词作名动汴京。十八岁嫁太学生赵明诚，夫妇志趣相投，共嗜金石书画，常“赌书泼茶”以为乐。靖康之变后南渡，赵明诚病逝途中，所藏金石文物散佚殆尽。孤身漂泊于杭州、金华等地，晚年再嫁张汝舟，旋因不堪虐待而诉讼离异，遭时人非议。南渡后词风由清丽婉约转为沉郁凄怆，创作《声声慢》《武陵春》《永遇乐》等名篇，以寻常语写深挚情，开创“易安体”，被誉为“千古第一才女”。约1155年卒于金华，享年约七十余岁"
