      "anecdote": "辛弃疾（1140-1207），字幼安，号稼轩，历城（今山东济南）人。生于金国占领区，自幼目睹汉人屈辱，立恢复中原之志。二十二岁聚众两千参加耿京义军，奉表南归途中闻叛徒张安国杀耿京降金，率五十骑突袭数万金营，擒张安国南归献俘。南归后历任湖北、湖南、江西安抚使，创建飞虎军，政绩卓著。一生力主北伐，上《美芹十论》《九议》陈抗金方略，然遭主和派排挤，屡被贬谪赋闲。闲居江西上饶带湖、铅山瓢泉二十余年，将报国之志熔铸于词，开创稼轩体，以豪放悲壮独步词坛。1207年抱恨病逝铅山，临终犹大呼“杀贼”"
