      "anecdote": "《诗经》是中国第一部诗歌总集，收录西周初年至春秋中叶305篇作品，作者涵盖各诸侯国贵族、士人、平民及民间歌者，大多不可考。无名诗人们以风、雅、颂三体，赋、比、兴三法，记录了周代社会生活的方方面面，举凡祭祀、农事、恋爱、战争无不入诗。其现实主义精神奠定了中国诗歌“饥者歌其食，劳者歌其事”的优良传统。相传孔子曾整理编定《诗》三百，汉代后尊为儒家经典。两千余年来，《诗经》始终是中国文学的不祧之祖"
