      "anecdote": "李贺（约790-约817），字长吉，河南福昌（今河南宜阳）人，唐宗室后裔。七岁能辞章，韩愈闻而访之，贺即赋《高轩过》震惊二公。因父名晋肃，避讳不得应进士举，仕途困顿，仅任奉礼郎微职。其诗想象奇崛诡谲，语言浓丽凄清，善写鬼魅幽冥，人称“诗鬼”。代表作《雁门太守行》“黑云压城城欲摧”意象奇绝，《李凭箜篌引》“石破天惊逗秋雨”瑰丽非凡。每旦骑瘦马背锦囊出游，得句即投其中，其母叹曰“是儿要当呕出心乃已尔”。年仅二十七岁病卒"
