      "anecdote": "柳永（约984-约1053），原名三变，字耆卿，崇安（今福建武夷山）人。屡试不第，自嘲“奉旨填词柳三变”，流连市井歌楼专攻词艺。景祐元年始中进士，官至屯田员外郎。他大量创制慢词长调，突破小令格局，极大扩展了词的表现容量。其词铺叙白描、雅俗共赏，名句“多情自古伤离别”“衣带渐宽终不悔”传诵千古。当时“凡有井水处即能歌柳词”，足见流传之广。约皇祐五年病逝，家贫无财，群妓合资葬之"
