        "poem": "环滁皆山也。其西南诸峰，林壑尤美。\n望之蔚然而深秀者，琅琊也。\n……\n醉翁之意不在酒，在乎山水之间也。\n山水之乐，得之心而寓之酒也。\n……\n已而夕阳在山，人影散乱，太守归而宾客从也。\n树林阴翳，鸣声上下，游人去而禽鸟乐也。\n然而禽鸟知山林之乐，而不知人之乐；\n人知从太守游而乐，而不知太守之乐其乐也。\n醉能同其乐，醒能述以文者，太守也。\n太守谓谁？庐陵欧阳修也。",
