        "poem": "咏怀诗·其一\n夜中不能寐，起坐弹鸣琴。\n薄帷鉴明月，清风吹我襟。\n孤鸿号外野，翔鸟鸣北林。\n徘徊将何见？忧思独伤心。\n\n咏怀诗·其十七\n独坐空堂上，谁可与欢者？\n出门临永路，不见行车马。\n登高望九州，悠悠分旷野。\n孤鸟西北飞，离兽东南下。\n日暮思亲友，晤言用自写。",
