      "anecdote": "嵇康（224—263），谯国铚县人，三国魏文学家、音乐家，“竹林七贤”精神领袖。官中散大夫，世称嵇中散。尚老庄，倡“越名教而任自然”，风骨凛然。四言诗继《诗经》后又开新境，《赠秀才入军》“目送归鸿，手挥五弦”千古传诵。因拒与司马氏合作，遭构陷被诛，临刑索琴弹《广陵散》，叹“于今绝矣”，以生命铸就魏晋风骨最高典范。"
