      "anecdote": "晏殊（991—1055），抚州临川人，北宋词人、政治家。十四岁以神童召试赐进士，官至宰相，世称“晏元献”。喜宾客好宴饮，范仲淹、欧阳修等多出其门下。词风婉约闲雅，圆融清丽，开北宋词坛富贵气象，被誉为“宰相词人”。《浣溪沙》“无可奈何花落去，似曾相识燕归来”对仗精工意蕴悠远；《蝶恋花》“独上高楼，望尽天涯路”被王国维引为治学第一境。至和二年病卒，年六十五。"
