      "anecdote": "张九龄（约673-740），字子寿，号曲江，韶州曲江（今广东韶关）人，盛唐名相、诗人。长安年间进士及第，历任中书舍人、集贤院学士等职，开元二十二年（734年）拜中书令，为开元盛世最后一位贤相。他执政期间正直敢言，举荐孟浩然、王维等后进，任人唯贤。后遭李林甫排挤，被贬为荆州长史。贬谪期间创作了大量感怀之作，诗风高雅蕴藉、寄托深远。代表作《感遇》'草木有本心，何求美人折'自喻高洁；《望月怀远》'海上生明月，天涯共此时'为千古中秋名句。其五言古诗成就尤高，上承陈子昂，下启王维、孟浩然，开盛唐山水诗之先声。开元二十八年（740年）病逝于曲江家中，享年约六十八岁。"
