      "anecdote": "贾岛（779-843），字浪仙，范阳（今河北涿州）人，中唐苦吟派诗人代表。早年出家为僧，法号无本，后得韩愈赏识，还俗参加科举，但屡试不第，仅任长江主簿等小官，世称'贾长江'。其诗以五律见长，极重炼字，刻意求工，与孟郊并称'郊寒岛瘦'。最著名的典故是骑驴吟'鸟宿池边树，僧敲（推）月下门'时冲撞韩愈仪仗，韩愈不仅不怒，还帮他定夺'敲'字更佳，二人由此定交。《寻隐者不遇》'松下问童子，言师采药去。只在此山中，云深不知处'寓问于答，含蓄隽永；《剑客》'十年磨一剑，霜刃未曾试'借剑喻志，风格豪健。其苦吟精神对后世影响深远。会昌三年（843年）病逝于普州司仓参军任上，享年六十四岁。"
