      "anecdote": "梅尧臣（1002-1060），字圣俞，宣州宣城（今安徽宣城）人，北宋诗人，世称'梅宛陵'。早年屡试不第，后因叔父梅询恩荫入仕，历任州县官、国子监直讲，官至尚书都官员外郎。他是宋诗革新运动的先驱，与苏舜钦并称'苏梅'，对欧阳修影响极大，被誉为宋诗'开山祖师'。他提出'状难写之景如在目前，含不尽之意见于言外'的创作理论，主张诗歌关注现实、语言平淡自然，开宋诗议论化、散文化先河。《鲁山山行》'人家在何许，云外一声鸡'意境深远；《陶者》'陶尽门前土，屋上无片瓦'深刻揭露社会不公；《东溪》'野凫眠岸有闲意，老树着花无丑枝'写景寓理。嘉祐五年（1060年）病逝于开封，享年五十九岁，欧阳修为其撰墓志铭。"
