      "anecdote": "张孝祥（1132-1170），字安国，号于湖居士，历阳乌江（今安徽和县）人，南宋豪放派词人。绍兴二十四年（1154年）状元及第，因上书为岳飞辩冤而触怒秦桧，遭打击报复。秦桧死后起复，历任中书舍人、建康留守等职，始终力主抗金北伐。其词慷慨激昂、气势磅礴，上承苏轼，下启辛弃疾，是辛派词人先驱。《念奴娇·过洞庭》'尽挹西江，细斟北斗，万象为宾客'以壮阔想象展现豪迈胸襟，'表里俱澄澈'更显人格高洁；《六州歌头·长淮望断》'使行人到此，忠愤气填膺，有泪如倾'悲壮慷慨，据载宋孝宗读后为之动容。他英年早逝，乾道六年（1170年）在芜湖病逝，年仅三十九岁。虽享年不永，但创作颇丰，有《于湖居士文集》传世。"
