      "anecdote": "岳飞（1103-1142），字鹏举，相州汤阴（今河南汤阴）人，南宋抗金名将、民族英雄、爱国词人。出身农家，宣和四年（1122年）从军，以战功累升至太尉、少保，任湖北、京西路宣抚使。他率领岳家军屡破金兵，郾城大捷后一度进军至距开封仅四十五里的朱仙镇，却因宋高宗与秦桧力主和议，一日内连收十二道金牌召回，以'莫须有'罪名下狱。其诗词虽存世不多，却篇篇震撼人心。《满江红·怒发冲冠》'三十功名尘与土，八千里路云和月''待从头、收拾旧山河，朝天阙'慷慨激昂、气壮山河，成为千古爱国绝唱；《小重山》'欲将心事付瑶琴，知音少，弦断有谁听'则抒写壮志难酬的孤愤。绍兴十一年十二月二十九日（1142年1月27日），岳飞在杭州风波亭被冤杀，年仅三十九岁。宋孝宗即位后平反昭雪，追谥武穆，后改谥忠武。"
