      "anecdote": "文天祥（1236-1283），字宋瑞，号文山，吉州庐陵（今江西吉安）人，南宋末爱国诗人、民族英雄。宝祐四年（1256年）状元及第，历任湖南提刑、赣州知州等职。德祐元年（1275年）元兵南侵，他散尽家财起兵勤王。次年任右丞相兼枢密使，出使元营被扣，逃脱后继续组织抗元，终在广东海丰五坡岭兵败被俘。被押解北上途中经零丁洋，写下《过零丁洋》'人生自古谁无死，留取丹心照汗青'的千古名句。押至大都（今北京）后，元世祖忽必烈亲自劝降，许以宰相高位，文天祥坚辞不受。在狱中三年，作《正气歌》'天地有正气，杂然赋流形''时穷节乃见，一一垂丹青'，以浩然正气彪炳千秋。至元十九年十二月九日（1283年1月9日）在大都柴市从容就义，年仅四十七岁。"
