      "anecdote": "司马相如（约前179—约前118），蜀郡成都人，西汉著名辞赋家，汉赋四大家之首。少时好读书击剑，景帝时以赀为郎，后客游梁国。因《子虚赋》得武帝赏识，又作《上林赋》，极尽铺陈之能事，奠定汉赋典范。曾奉使西南夷，为沟通汉与西南少数民族关系作出贡献。晚年称病闲居。其赋作铺张扬厉、辞藻宏丽，代表作《子虚赋》《上林赋》《长门赋》等。与卓文君的爱情故事传为千古佳话。卒于茂陵。"
