      "anecdote": "班固（32—92），扶风安陵人，东汉史学家、辞赋家，汉赋四大家之一。幼年聪慧，九岁能属文，十六岁入太学博览群书。父班彪去世后继志修史，历时二十余年完成《汉书》，为中国第一部纪传体断代史，与《史记》并称。因窦宪案受牵连入狱，卒于狱中，年六十一。代表作有《两都赋》《咏史》等，其中《咏史》为中国现存最早文人五言诗。与司马迁并称“班马”。"
