        "poem": "余每观才士之所作，窃有以得其用心。夫放言遣辞，良多变矣，妍蚩好恶，可得而言。每自属文，尤见其情。恒患意不称物，文不逮意。盖非知之难，能之难也。故作《文赋》，以述先士之盛藻，因论作文之利害所由，他日殆可谓曲尽其妙。\n\n其始也，皆收视反听，耽思傍讯。精骛八极，心游万仞。其致也，情曈昽而弥鲜，物昭晰而互进。倾群言之沥液，漱六艺之芳润。浮天渊以安流，濯下泉而潜浸。……笼天地于形内，挫万物于笔端。",
