        "poem": "长安大道连狭斜，青牛白马七香车。\n玉辇纵横过主第，金鞭络绎向侯家。\n龙衔宝盖承朝日，凤吐流苏带晚霞。\n百尺游丝争绕树，一群娇鸟共啼花。\n……\n得成比目何辞死，愿作鸳鸯不羡仙。\n……\n节物风光不相待，桑田碧海须臾改。\n昔时金阶白玉堂，即今惟见青松在。\n寂寂寥寥扬子居，年年岁岁一床书。\n独有南山桂花发，飞来飞去袭人裾。",
