      "anecdote": "贺知章（约659—约744），越州永兴人，盛唐诗人。武后证圣元年进士，历任国子四门博士、太常博士、礼部侍郎、集贤院学士，最后官至秘书监。天宝初请为道士还乡，玄宗赐鉴湖一曲。为人旷达豪放，谈笑风生，人称“诗狂”。与李白、张旭等交游，为“饮中八仙”之一。初见李白惊呼“谪仙人”，金龟换酒畅饮，传为文坛佳话。代表作《回乡偶书》《咏柳》千古传诵，存诗仅二十首却篇篇精品。"
