      "anecdote": "韦庄（约836—约910），京兆杜陵人，晚唐至五代诗人、词人，花间派核心。韦应物四世孙，早年应举不第，流寓江南十余年。乾宁元年进士，后入蜀依附王建，官至吏部侍郎同平章事。长篇叙事诗《秦妇吟》以黄巢起义为背景，“内库烧为锦绣灰，天街踏尽公卿骨”写战乱惨状，时人称为“秦妇吟秀才”。词作与温庭筠并称“温韦”，为花间派两大核心。《菩萨蛮》五首清丽婉约，为词史上乘之作。"
