      "anecdote": "陈子龙（1608—1647），南直隶松江华亭人，明末诗人、词人，云间派领袖。崇祯十年进士，曾任绍兴推官，擢兵科给事中。清军破南京后，在松江起兵抗清，兵败逃亡。后联络太湖义军继续抗清，事泄被捕，在被押送南京途中乘间投水殉国，年四十。其词婉约中见沉郁，开清词中兴之局。诗学盛唐，慷慨悲歌，代表作《秋日杂感》《渡易水》等寄托故国之思。学生夏完淳亦少年抗清就义，师徒皆为忠烈。"
