      "anecdote": "王士祯（1634—1711），山东新城人，清初诗人，神韵说创始人。顺治十五年进士，历任扬州推官、国子监祭酒、左都御史、刑部尚书等职。主盟清初诗坛数十年，门生遍天下。创立“神韵说”诗论，强调“不着一字，尽得风流”，以淡远含蓄为宗。代表作《秋柳》四首传诵大江南北，一时和者甚众。另有《真州绝句》“半江红树卖鲈鱼”等清新淡远之作。与朱彝尊并称“南朱北王”。"
