      "anecdote": "郑燮（1693—1765），号板桥，江苏兴化人，清代书画家、文学家，扬州八怪之首。乾隆元年进士，曾任山东范县、潍县知县。为官清廉，关心民瘼，在潍县开仓赈灾，却因此得罪豪绅，罢官归里。书法自创“六分半书”，绘画以竹、兰、石著称，尤以墨竹名世。诗书画三绝，题画诗独树一帜。《竹石》“咬定青山不放松”借竹喻人，刚正之气千古传诵。以“难得糊涂”闻名后世，影响深远。"
